"""
add_open_models.py: adds free, open AI models (no API key) to the Dubai urban heat dashboard.

Usage:
    python add_open_models.py dubai_uhi_dashboard.html            # writes dubai_uhi_dashboard_open_models.html
    python add_open_models.py in.html out.html

What it changes:
  * The "Ask the map" prompt bar gets a model picker: built-in rules, open models that run
    inside the browser (Qwen, Llama, Phi, Gemma, Mistral, SmolLM via WebLLM + WebGPU),
    Ollama models on this computer, or models added in the AI models panel.
  * Every question is read by the chosen model, which sets the map, filters, month and
    what-if; the numbers are always computed by the dashboard. The model then words the answer.
  * "Compare models" runs the same prompt through several models and shows each reading.
  * The chosen model also answers the dashboard's other AI features.
Safe to run again on an already patched file.
"""
import re
import sys

BLOCK = '<!--OPENMODELS-START--><style>\n#ombox{margin-top:10px;padding-top:10px;border-top:1px solid #2c3a47}\n#ombox .row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}\n#ombox label{font-size:.82rem;color:#c9d2d8;display:flex;align-items:center;gap:6px}\n#omsel{font:inherit;font-size:.92rem;padding:7px 8px;border-radius:6px;border:0;min-width:300px;max-width:100%;background:#fff;color:#17212b}\n#omload{font:inherit;font-size:.82rem;padding:6px 12px;border-radius:6px;border:1px solid #3d4d5c;background:#2c3a47;color:#e7ecee;cursor:pointer}\n#omstat{font-size:.8rem;color:#c9d2d8;flex:1;min-width:200px}\n#omprog{height:6px;background:#2c3a47;border-radius:3px;margin-top:8px;overflow:hidden;display:none}\n#omprog i{display:block;height:100%;width:0;background:#4fb3a9;transition:width .2s}\n#omcmpl{display:none;flex-wrap:wrap;gap:6px;margin-top:8px}\n#omcmpl label{background:#2c3a47;border:1px solid #3d4d5c;border-radius:14px;padding:3px 10px;font-size:.8rem;cursor:pointer}\n#omnote{font-size:.76rem;color:#9fb0bc;margin:8px 0 0}\n#omcards{display:none;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:10px;margin-top:12px}\n#omcards>div{background:#fff;color:var(--ink);border-radius:8px;padding:10px;font-size:.88rem;display:flex;flex-direction:column;gap:6px}\n#omcards h4{margin:0;font-size:.9rem;color:#1f3d7a}\n#omcards .tags{display:flex;flex-wrap:wrap;gap:4px}\n#omcards .tag{background:#eef3f7;border-radius:4px;padding:1px 6px;font-size:.74rem;color:#1f3d7a}\n#omcards button{align-self:flex-start;font:inherit;font-size:.8rem;padding:4px 10px;border-radius:5px;border:1px solid #c4cacd;background:#f6f7f6;cursor:pointer}\n#omcards .src{font-size:.74rem;color:#5b6670}\n</style><script>\n(function(){\nif (!window.PROMPTBAR) return;                       // needs the "Ask the map" prompt bar\nconst PB = window.PROMPTBAR, esc = PB.esc;\nconst WEBLLM_URL = \'https://cdn.jsdelivr.net/npm/@mlc-ai/web-llm@0.2.85/+esm\';\nconst OLLAMA = \'http://localhost:11434\';\nconst realFetch = (window.AIX && window.AIX.realFetch) || window.fetch.bind(window);\n\n// Open models that run inside the browser with WebGPU (free, no key, no server).\n// [WebLLM model id, label, approx. download in GB]\nconst BROWSER = [\n  [\'Qwen2.5-1.5B-Instruct-q4f16_1-MLC\', \'Qwen2.5 1.5B · recommended\', 1.6],\n  [\'Qwen3-1.7B-q4f16_1-MLC\', \'Qwen3 1.7B\', 2.0],\n  [\'Qwen3.5-2B-q4f16_1-MLC\', \'Qwen3.5 2B\', 2.2],\n  [\'Qwen2.5-3B-Instruct-q4f16_1-MLC\', \'Qwen2.5 3B · better, slower\', 2.5],\n  [\'Qwen3-4B-q4f16_1-MLC\', \'Qwen3 4B · most capable Qwen here\', 3.4],\n  [\'Llama-3.2-3B-Instruct-q4f16_1-MLC\', \'Llama 3.2 3B (Meta)\', 2.3],\n  [\'Phi-4-mini-instruct-q4f16_1-MLC\', \'Phi-4 mini (Microsoft)\', 3.4],\n  [\'Ministral-3-3B-Instruct-2512-BF16-q4f16_1-MLC\', \'Ministral 3 3B (Mistral)\', 2.9],\n  [\'SmolLM2-1.7B-Instruct-q4f16_1-MLC\', \'SmolLM2 1.7B (Hugging Face)\', 1.8],\n  [\'gemma3-1b-it-q4f16_1-MLC\', \'Gemma 3 1B (Google) · smallest\', 0.7],\n];\nconst OM = window.OM = {engine: null, loaded: null, lib: null, ollama: [], queue: Promise.resolve(), BROWSER};\nconst hasGPU = !!navigator.gpu;\n\n// ---------- UI inside the "Ask the map" bar\nconst keyRow = $(\'pkey\') && $(\'pkey\').closest(\'.row\'); if (keyRow) keyRow.style.display = \'none\';\nconst box = document.createElement(\'div\'); box.id = \'ombox\';\nbox.innerHTML = `<div class="row">\n  <label for="omsel">Model</label><select id="omsel"></select>\n  <button id="omload" type="button">Load model</button>\n  <label><input type="checkbox" id="omcmp"> Compare models</label>\n  <span id="omstat"></span></div>\n <div id="omprog"><i></i></div>\n <div id="omcmpl"></div>\n <p id="omnote"></p>`;\n$(\'pres\').before(box);\nconst cards = document.createElement(\'div\'); cards.id = \'omcards\'; $(\'pres\').after(cards);\n\nconst aixKey = p => p.provider + \'|\' + p.model;\nfunction parse(v){\n  if (!v || v === \'rules\') return {kind: \'rules\', label: \'built-in rules\'};\n  if (v.startsWith(\'web:\')) { const id = v.slice(4), b = BROWSER.find(x => x[0] === id); return {kind: \'web\', id, label: (b ? b[1].split(\' · \')[0] : id) + \' (in this browser)\'}; }\n  if (v.startsWith(\'ollama:\')) return {kind: \'ollama\', id: v.slice(7), label: v.slice(7) + \' (Ollama)\'};\n  if (v.startsWith(\'aix:\')) { const p = window.AIX && AIX.profiles.find(x => !x.omTemp && aixKey(x) === v.slice(4)); return p ? {kind: \'aix\', p, label: AIX.label(p)} : {kind: \'rules\', label: \'built-in rules\'}; }\n  return {kind: \'rules\', label: \'built-in rules\'};\n}\nfunction options(){\n  const o = [\'<option value="rules">No AI: built-in rules (instant)</option>\'];\n  o.push(`<optgroup label="Open models in this browser: free, no key${hasGPU ? \'\' : \' (needs WebGPU: Chrome or Edge)\'}">` +\n    BROWSER.map(([id, l, gb]) => `<option value="web:${id}" ${hasGPU ? \'\' : \'disabled\'}>${esc(l)} · ~${gb} GB first download</option>`).join(\'\') + \'</optgroup>\');\n  o.push(\'<optgroup label="Open models via Ollama on this computer">\' + (OM.ollama.length\n    ? OM.ollama.map(n => `<option value="ollama:${esc(n)}">${esc(n)}</option>`).join(\'\')\n    : \'<option disabled>None found (install from ollama.com, start with OLLAMA_ORIGINS=*)</option>\') + \'</optgroup>\');\n  const own = window.AIX ? AIX.profiles.filter(p => !p.omTemp) : [];\n  if (own.length) o.push(\'<optgroup label="Models added in the AI models panel">\' +\n    own.map(p => `<option value="aix:${esc(aixKey(p))}">${esc(AIX.label(p))}</option>`).join(\'\') + \'</optgroup>\');\n  return o.join(\'\');\n}\nfunction fill(){\n  const cur = $(\'omsel\').value || store(\'om-model\') || \'rules\';\n  $(\'omsel\').innerHTML = options();\n  $(\'omsel\').value = [...$(\'omsel\').options].some(o => o.value === cur && !o.disabled) ? cur : \'rules\';\n  const picked = new Set([...$(\'omcmpl\').querySelectorAll(\'input:checked\')].map(i => i.value));\n  $(\'omcmpl\').innerHTML = [...$(\'omsel\').options].filter(o => !o.disabled).map(o =>\n    `<label><input type="checkbox" value="${esc(o.value)}" ${picked.has(o.value) ? \'checked\' : \'\'}> ${esc(o.textContent.split(\' · ~\')[0])}</label>`).join(\'\');\n  onPick(false);\n}\nlet fillLock = false;\nfunction safeFill(){ if (fillLock) return; fillLock = true; try { fill(); } finally { fillLock = false; } }\nfunction store(k, v){ try { if (v === undefined) return localStorage.getItem(k); localStorage.setItem(k, v); } catch (e) { return null; } }\nfunction status(t){ $(\'omstat\').textContent = t || \'\'; }\nfunction progress(f){ const p = $(\'omprog\'); if (f == null) { p.style.display = \'none\'; return; } p.style.display = \'block\'; p.firstElementChild.style.width = Math.round(f * 100) + \'%\'; }\nfunction onPick(save = true){\n  const v = $(\'omsel\').value, m = parse(v);\n  if (save) store(\'om-model\', v);\n  $(\'omload\').style.display = m.kind === \'web\' && OM.loaded !== m.id ? \'\' : \'none\';\n  $(\'omnote\').innerHTML = {\n    rules: \'Keyword rules read your question. Pick an open model above to have an AI read it instead; the map, table and numbers are always computed by the dashboard.\',\n    web: \'Runs entirely in this browser on your graphics card: free, private and no API key. The first use downloads the model once (it is then cached); after that it works offline.\',\n    ollama: \'Runs on this computer through Ollama: free and no API key.\',\n    aix: \'Uses a model you added in the AI models panel.\'}[m.kind];\n  setDefault(v);\n}\n// keep the rest of the dashboard\'s AI features (Ask AI, plans, image reading) on the same model\nfunction setDefault(v){\n  if (!window.AIX) return;\n  const m = parse(v);\n  AIX.profiles = AIX.profiles.filter(p => !p.omTemp);\n  AIX.profiles.forEach(p => p.def = false);\n  if (m.kind === \'web\') AIX.profiles.push({provider: \'webllm\', kind: \'webllm\', base: \'\', model: m.id, key: \'\', vision: false, def: true, cmp: false, omTemp: true});\n  else if (m.kind === \'ollama\') AIX.profiles.push({provider: \'ollama\', kind: \'openai\', base: OLLAMA + \'/v1\', model: m.id, key: \'\', vision: false, def: true, cmp: false, omTemp: true});\n  else if (m.kind === \'aix\') m.p.def = true;\n  if (AIX.redraw) AIX.redraw();\n}\n\n// ---------- engines\nasync function lib(){ return OM.lib || (OM.lib = window.OM_WEBLLM || await import(WEBLLM_URL)); }\nasync function resolveId(id){\n  try { const a = await navigator.gpu.requestAdapter(); const L = await lib();\n    if (a && !a.features.has(\'shader-f16\')) { const alt = id.replace(\'q4f16_1\', \'q4f32_1\');\n      if (alt !== id && L.prebuiltAppConfig.model_list.some(r => r.model_id === alt)) return alt; } } catch (e) {}\n  return id;\n}\nfunction serial(fn){ const r = OM.queue.then(fn, fn); OM.queue = r.catch(() => {}); return r; }\nasync function engineFor(id){\n  if (OM.engine && OM.loaded === id) return OM.engine;\n  const L = await lib(), real = await resolveId(id);\n  const name = (BROWSER.find(b => b[0] === id) || [0, id])[1].split(\' · \')[0];\n  const cb = r => { progress(r.progress); status(`Loading ${name}: ${Math.round((r.progress || 0) * 100)}%` + (r.progress < 1 ? \' (first time downloads the model; later loads use the cache)\' : \'\')); };\n  status(`Loading ${name}…`); progress(0);\n  try {\n    if (!OM.engine) OM.engine = await L.CreateMLCEngine(real, {initProgressCallback: cb}, {context_window_size: 8192});\n    else { OM.engine.setInitProgressCallback(cb); await OM.engine.reload(real, {context_window_size: 8192}); }\n  } catch (e) { OM.engine = null; OM.loaded = null; progress(null); throw new Error(/memory|device|lost/i.test(e.message) ? \'not enough graphics memory for this model; choose a smaller one\' : e.message); }\n  OM.loaded = id; progress(null); status(`${name} ready`);\n  if ($(\'omsel\').value === \'web:\' + id) $(\'omload\').style.display = \'none\';\n  return OM.engine;\n}\nconst noThink = id => /qwen3/i.test(id);\nfunction stripThink(t){ return String(t || \'\').replace(/<think>[\\s\\S]*?(<\\/think>|$)/g, \'\').trim(); }\nfunction jsonOf(t){ const m = stripThink(t).replace(/```(json)?/g, \'\').match(/\\{[\\s\\S]*\\}/); if (!m) throw new Error(\'the model did not return JSON\');\n  try { return JSON.parse(m[0]); } catch (e) { return JSON.parse(m[0].replace(/,\\s*([}\\]])/g, \'$1\').replace(/\'/g, \'"\')); } }\n\n// one chat call, any open model. messages = [{role, content}]\nOM.chat = function(m, messages, opt = {}){\n  if (m.kind === \'web\') return serial(async () => {\n    const eng = await engineFor(m.id);\n    const req = {messages, temperature: opt.temperature ?? 0, max_tokens: opt.max_tokens || 400};\n    if (noThink(m.id)) req.extra_body = {enable_thinking: false};\n    if (opt.onToken && !opt.json) {\n      const it = await eng.chat.completions.create({...req, stream: true}); let out = \'\';\n      for await (const ch of it) { out += ch.choices[0]?.delta?.content || \'\'; opt.onToken(stripThink(out)); }\n      return stripThink(out);\n    }\n    let r;\n    try { r = await eng.chat.completions.create(opt.json ? {...req, response_format: {type: \'json_object\'}} : req); }\n    catch (e) { if (!opt.json) throw e; r = await eng.chat.completions.create(req); }\n    return stripThink(r.choices[0].message.content);\n  });\n  if (m.kind === \'ollama\') return (async () => {\n    const body = {model: m.id, messages, stream: false, options: {temperature: opt.temperature ?? 0, num_predict: opt.max_tokens || 400}};\n    if (opt.json) body.format = \'json\';\n    if (/qwen3/i.test(m.id)) body.think = false;\n    let r = await realFetch(OLLAMA + \'/api/chat\', {method: \'POST\', headers: {\'Content-Type\': \'application/json\'}, body: JSON.stringify(body)});\n    if (r.status === 400 && \'think\' in body) { delete body.think; r = await realFetch(OLLAMA + \'/api/chat\', {method: \'POST\', headers: {\'Content-Type\': \'application/json\'}, body: JSON.stringify(body)}); }\n    const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || (\'HTTP \' + r.status));\n    return stripThink(j.message && j.message.content);\n  })();\n  if (m.kind === \'aix\') return AIX.call(m.p, [{text: messages.map(x => x.content).join(\'\\n\\n\')}], {json: opt.json, temperature: opt.temperature ?? 0}).then(stripThink);\n  return Promise.reject(new Error(\'no model\'));\n};\n\n// AI models panel: open in-browser models become a provider too\nif (window.AIX) {\n  AIX.PRE.webllm = {name: \'Open model in this browser (free, no key)\', kind: \'webllm\', base: \'\', nokey: true, signup: \'\', models: BROWSER.map(b => [b[0], 0])};\n  const axp = document.getElementById(\'axp\'); if (axp && hasGPU) axp.insertAdjacentHTML(\'afterbegin\', \'<option value="webllm">Open model in this browser (free, no key)</option>\');\n  const orig = AIX.call;\n  AIX.call = async function(p, parts, opt = {}){\n    if (p.kind !== \'webllm\') return orig.call(AIX, p, parts, opt);\n    const text = parts.filter(x => x.text).map(x => x.text).join(\'\\n\') + (parts.some(x => x.inline_data) ? \'\\n(An image was available but this model reads text only.)\' : \'\') + (opt.json ? \'\\nReply with one JSON object only, no other text.\' : \'\');\n    const out = await OM.chat({kind: \'web\', id: p.model}, [{role: \'user\', content: text}], {json: !!opt.json, temperature: opt.temperature, max_tokens: 900});\n    if (opt.json) { const m = out.match(/\\{[\\s\\S]*\\}/); return m ? m[0] : out; }\n    return out;\n  };\n  document.addEventListener(\'aix-change\', () => safeFill());\n}\n\n// ---------- reading the question with an open model (compact prompt for small models)\nconst short = s => String(s).replace(/ \\(.*\\)/, \'\');\nfunction candidates(q){\n  const t = q.toLowerCase(), words = t.split(/[^a-z0-9\']+/).filter(w => w.length >= 4);\n  const hit = D.locs.filter(n => n !== \'Dubai\' && (t.includes(n.toLowerCase()) || words.some(w => n.toLowerCase().split(/\\s+/).includes(w))));\n  return hit.slice(0, 25);\n}\nasync function planWith(m, q){\n  const draft = PB.rulesPlan(q); delete draft.source;\n  const cands = candidates(q);\n  const ivs = typeof IV !== \'undefined\' ? Object.fromEntries(Object.entries(IV).map(([k, v]) => [k, v.label])) : {};\n  const sys = \'You turn questions about a Dubai urban heat dashboard into a JSON filter. Reply with one JSON object only.\';\n  const user = `JSON keys (use null when not asked):\n"from","to": months "YYYY-MM" from ${D.months[0]} to ${D.months[NM - 1]}; latest month with good data ${D.months[D.latest]}; summer = Jun-Sep; "now" = latest.\n"variable": one of ${JSON.stringify(Object.fromEntries(Object.entries(D.vars).map(([k, v]) => [k, short(v[0])])))}\n"place_type": one of ${JSON.stringify(D.ptypes)}\n"zone": one of ${JSON.stringify(D.zones)}\n"localities": list of area names, only from ${cands.length ? JSON.stringify(cands) : \'[] (no area named)\'}\n"only_hotspots": true if asking about hotspots or hottest places; "order": "desc" (hottest/highest) or "asc" (coolest/lowest); "top_n": 1-50\n"compare": true to compare named areas over time\n"intervention": null or {"key": one of ${JSON.stringify(ivs)}, "percent": 0-100}\n"image": null, "lst" or "hot"; "play": true to animate months\nA keyword parser drafted this; keep what is right and fix what is wrong:\n${JSON.stringify(draft)}\nQuestion: ${q}`;\n  const txt = await OM.chat(m, [{role: \'system\', content: sys}, {role: \'user\', content: user}], {json: true, max_tokens: 300});\n  const P = jsonOf(txt);\n  for (const k of [\'top_n\', \'order\']) if (P[k] == null) P[k] = draft[k];\n  if (P.localities == null) P.localities = draft.localities;\n  return P;\n}\nfunction facts(R){\n  const r1 = x => typeof x === \'number\' ? Math.round(x * 100) / 100 : x;\n  const f = Object.fromEntries(Object.entries(R).filter(([k]) => !k.startsWith(\'_\')));\n  f.top = (f.top || []).slice(0, 5).map(t => Object.fromEntries(Object.entries(t).map(([k, v]) => [k, r1(v)])));\n  for (const k of [\'threshold\', \'typical\', \'mean\']) f[k] = r1(f[k]);\n  if (f.intervention) f.intervention = Object.fromEntries(Object.entries(f.intervention).map(([k, v]) => [k, r1(v)]));\n  if (f.compare) f.compare = f.compare.map(c => Object.fromEntries(Object.entries(c).map(([k, v]) => [k, r1(v)])));\n  return f;\n}\nfunction answerWith(m, q, R, onToken){\n  const sys = \'You are an urban climate analyst for Dubai. Use ONLY the RESULTS given. Copy numbers exactly as given; never invent places or numbers. Write 3-5 plain sentences: the month, the key places and numbers, and one limitation (Landsat land-surface temperature is the ground surface at about 10:40, not air temperature).\';\n  return OM.chat(m, [{role: \'system\', content: sys}, {role: \'user\', content: `Question: ${q}\\nRESULTS: ${JSON.stringify(facts(R))}`}], {max_tokens: 350, temperature: 0.2, onToken});\n}\nfunction tagsOf(P, R){\n  return [`Month ${R.month}`, short(R.variable), P.place_type, P.zone, ...(P.localities || []), P.only_hotspots ? \'hotspots only\' : null,\n    `${P.order === \'asc\' ? \'coolest\' : \'top\'} ${P.top_n}`, P.intervention ? `What if: ${IV[P.intervention.key].label}, ${P.intervention.percent}%` : null,\n    P.compare ? \'compare areas\' : null].filter(Boolean);\n}\n\n// ---------- the new "Show me": every question goes through the chosen model(s)\nOM.go = async function(q){\n  if (!q) return;\n  const primary = $(\'omsel\').value;\n  const list = [primary, ...($(\'omcmp\').checked ? [...$(\'omcmpl\').querySelectorAll(\'input:checked\')].map(i => i.value) : [])].filter((v, i, a) => a.indexOf(v) === i);\n  $(\'pres\').style.display = \'block\'; $(\'pres\').innerHTML = \'<p class="note">Working…</p>\';\n  cards.style.display = list.length > 1 ? \'grid\' : \'none\'; cards.innerHTML = \'\';\n  const res = [];\n  for (const v of list) {\n    const m = parse(v); let P, src = m.label;\n    if (m.kind === \'rules\') P = PB.rulesPlan(q);\n    else { status(`Reading the question with ${m.label}…`);\n      try { P = await planWith(m, q); } catch (e) { P = PB.rulesPlan(q); src = `built-in rules, because ${m.label} failed: ${e.message}`; } }\n    P = PB.clean(P); res.push({v, m, P, src});\n  }\n  // compute every model\'s result on the dashboard, then leave the map on the first model\'s reading\n  res.forEach(r => { r.R = PB.run(r.P); r.answer = PB.template(r.R, r.P); });\n  const show = r => { PB.run(r.P); PB.show(r.P, r.R, r.answer, r.src); };\n  show(res[0]);\n  if (res.length > 1) {\n    cards.innerHTML = res.map((r, i) => `<div><h4>${esc(r.m.label)}</h4><div class="tags">${tagsOf(r.P, r.R).map(t => `<span class="tag">${esc(t)}</span>`).join(\'\')}</div>\n      <div id="omans${i}">${esc(r.answer)}</div><span class="src">${r.src === r.m.label ? \'Understood by this model\' : esc(r.src)}</span>\n      <button data-i="${i}" type="button">${i ? \'Show this on the map\' : \'Shown on the map\'}</button></div>`).join(\'\');\n    cards.querySelectorAll(\'button\').forEach(b => b.onclick = () => { const r = res[+b.dataset.i]; show(r);\n      cards.querySelectorAll(\'button\').forEach(x => x.textContent = x === b ? \'Shown on the map\' : \'Show this on the map\'); });\n  }\n  // let each model write its answer in words (numbers come from the dashboard)\n  for (const [i, r] of res.entries()) {\n    if (r.m.kind === \'rules\' || r.src !== r.m.label) continue;\n    status(`${r.m.label} is writing the answer…`);\n    const el = () => (i === 0 && $(\'pans\')) ? [$(\'pans\'), document.getElementById(\'omans\' + i)] : [document.getElementById(\'omans\' + i)];\n    try {\n      const t = await answerWith(r.m, q, r.R, s => el().forEach(e => e && (e.textContent = s)));\n      if (t) { r.answer = t; el().forEach(e => e && (e.textContent = t)); }\n    } catch (e) { el().forEach(x => x && (x.textContent = r.answer + ` (${r.m.label} couldn\'t write the answer: ${e.message})`)); }\n  }\n  status(list.some(v => parse(v).kind !== \'rules\') ? \'Done. Numbers, map and table come from the dashboard; the model only reads the question and words the answer.\' : \'\');\n};\n\n// ---------- wiring\n$(\'omsel\').onchange = () => onPick(true);\n$(\'omcmp\').onchange = () => { $(\'omcmpl\').style.display = $(\'omcmp\').checked ? \'flex\' : \'none\'; };\n$(\'omload\').onclick = () => { const m = parse($(\'omsel\').value); if (m.kind === \'web\') serial(() => engineFor(m.id)).catch(e => status(\'Could not load: \' + e.message)); };\nasync function findOllama(){\n  try { const c = new AbortController(); setTimeout(() => c.abort(), 1500);\n    const r = await realFetch(OLLAMA + \'/api/tags\', {signal: c.signal}); const j = await r.json();\n    OM.ollama = (j.models || []).map(x => x.name); } catch (e) { OM.ollama = []; }\n  safeFill();\n}\nsafeFill(); findOllama();\n})();\n</script><!--OPENMODELS-END-->\n'


def patch(html: str) -> str:
    # 1. expose the prompt bar's functions and let the new module take over "Show me"
    a, b = html.find("<!--PROMPT-START-->"), html.find("<!--PROMPT-END-->")
    if a < 0 or b < 0:
        sys.exit("This file has no 'Ask the map' prompt bar (PROMPT block) to extend.")
    prompt = html[a:b]
    if "window.PROMPTBAR" not in prompt:
        prompt = prompt.replace("$('pgo').onclick = go;",
                                "window.PROMPTBAR = {rulesPlan, aiPlan, clean, run, template, show, go, esc};\n$('pgo').onclick = go;", 1)
        prompt = re.sub(r"(async function go\(\)\{\s*const q = \$\('pq'\)\.value\.trim\(\); if \(!q\) return;)",
                        r"\1\n  if (window.OM && OM.go) return OM.go(q);", prompt, count=1)
        if "window.PROMPTBAR" not in prompt or "OM.go(q)" not in prompt:
            sys.exit("Could not find the expected code in the PROMPT block; the dashboard version may differ.")
    html = html[:a] + prompt + html[b:]

    # 2. let the AI models panel be refreshed from outside
    a, b = html.find("<!--AIX-START-->"), html.find("<!--AIX-END-->")
    if a >= 0 and b >= 0:
        aix = html[a:b]
        if "AIX.redraw" not in aix:
            i = aix.rfind("drawList();\n})();")
            if i >= 0:
                aix = aix[:i] + "AIX.redraw = drawList;\n" + aix[i:]
        html = html[:a] + aix + html[b:]

    # 3. add (or replace) the open-models module
    html = re.sub(r"<!--OPENMODELS-START-->.*?<!--OPENMODELS-END-->", "", html, flags=re.S)
    i = html.rfind("</body>")
    return html[:i] + BLOCK + html[i:]


if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    src = sys.argv[1]
    dst = sys.argv[2] if len(sys.argv) > 2 else re.sub(r"\.html?$", "", src) + "_open_models.html"
    with open(src, encoding="utf-8") as f:
        html = f.read()
    with open(dst, "w", encoding="utf-8") as f:
        f.write(patch(html))
    print(f"Wrote {dst}")
